-- Synthetic verified payments; no gateway/network calls. Everything rolls back.
begin;
set local lock_timeout='5s';set local statement_timeout='45s';
select set_config('request.jwt.claims','{}',true);
do $$declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();p uuid:=gen_random_uuid();g uuid:=gen_random_uuid();o uuid;q jsonb;r jsonb;begin
 insert into auth.users(id,email,email_confirmed_at)select id,'refund-qa-'||id||'@example.invalid',now()from unnest(array[u,v,a,s])id;
 insert into public.staff_roles(user_id,market,role)values(a,'PH','admin');
 insert into public.distributor_profiles(user_id,external_member_id,code,display_name,market,active,verified_at)values(s,'QA-'||s,'Q'||replace(s::text,'-',''),'QA refund sponsor','PH',true,now());
 insert into public.sponsor_attributions(user_id,distributor_id)values(u,s);
 insert into public.products(id,slug,name,category,status)values(p,'refund-qa-'||p,'QA refundable goods','Nutrition','published'),(g,'refund-qa-'||g,'QA returned bonus','Nutrition','published');
 insert into public.product_offers(product_id,market,currency,retail_minor,regulatory_approved,approval_reference,max_quantity)values(p,'PH','PHP',100,true,'ROLLBACK-QA',24),(g,'PH','PHP',50,true,'ROLLBACK-QA',24);
 insert into public.inventory(product_id,market,on_hand)values(p,'PH',10),(g,'PH',10);
 update public.markets set online_sales_approved=true,payments_ready=true,policy_reference='ROLLBACK-QA'where code='PH';
 perform set_config('refund.user',u::text,true);perform set_config('refund.other',v::text,true);perform set_config('refund.admin',a::text,true);perform set_config('refund.product',p::text,true);perform set_config('refund.gift',g::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','aal','aal2')::text,true);
 perform public.approve_bonus_campaign('PH',jsonb_build_object('name','Synthetic refund gift','qualifyingProductId',p,'minimumQuantity',1,'bonusProductId',g,'bonusQuantity',1,'maximumPerOrder',1,'maximumUnits',10,'startsAt',now()-interval '1 day','endsAt',now()+interval '1 day','allowVoucher',false,'returnTerms','Synthetic return terms for returned bonus goods only.','capacityAfterRefund','retain'),'ROLLBACK-REFUND');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','aal','aal1')::text,true);
 q:=public.quote_fulfilment_checkout('PH',jsonb_build_array(jsonb_build_object('productId',p,'quantity',1)),null,'{"method":"delivery"}');
 o:=public.create_fulfilment_order('PH',jsonb_build_array(jsonb_build_object('productId',p,'quantity',1)),'{"full_name":"QA Customer","phone":"0000000000","line1":"QA fixture address","city":"Manila","postal_code":"1000","country":"PH"}',gen_random_uuid(),(select checkout_terms_version from public.markets where code='PH'),null,q->>'quoteHash',null,'{"method":"delivery"}');
 perform set_config('request.jwt.claims','{}',true);
 r:=public.prepare_stripe_checkout(o,u,false,'https://example.invalid');
 perform public.apply_stripe_checkout_event('evt_refund_'||o,(r->>'id')::uuid,o,'cs_test_refund_'||replace(o::text,'-',''),false,100,'php','complete','paid','pi_refund'||replace(o::text,'-',''));
 perform set_config('refund.order',o::text,true);
 perform set_config('refund.payment','pi_refund'||replace(o::text,'-',''),true);
 perform set_config('refund.item',(select id::text from public.order_items where order_id=o),true);
end $$;
set local role authenticated;
do $$declare c uuid;p uuid;r uuid;r2 uuid;items jsonb:=jsonb_build_array(jsonb_build_object('itemId',current_setting('refund.item'),'amountMinor',40));begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.other'),'role','authenticated','aal','aal1')::text,true);
 begin perform public.request_order_return(current_setting('refund.order')::uuid,'return','Synthetic request reason');raise exception 'FAIL: another customer return';exception when insufficient_privilege then null;end;
 begin perform public.return_context(current_setting('refund.order')::uuid);raise exception 'FAIL: another customer refund context';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.user'),'role','authenticated','aal','aal1')::text,true);
 c:=public.request_order_return(current_setting('refund.order')::uuid,'return','Synthetic request reason');perform set_config('refund.case',c::text,true);
 if public.request_order_return(current_setting('refund.order')::uuid,'return','Synthetic request reason')<>c then raise exception 'FAIL: duplicate return intake';end if;
 begin perform public.approve_order_refund(c,gen_random_uuid(),items,'QA-PART-ONE');raise exception 'FAIL: customer refund approval';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.admin'),'role','authenticated','aal','aal2')::text,true);
 begin perform public.approve_order_refund(c,gen_random_uuid(),items,'QA-PART-ONE');raise exception 'FAIL: no approved policy';exception when invalid_parameter_value then null;end;
 p:=public.approve_refund_policy('PH','QA-REFUND-V1','Synthetic approved refund policy for rollback-only testing.',true,'ROLLBACK-POLICY');perform set_config('refund.policy',p::text,true);
 r:=public.approve_order_refund(c,p,items,'QA-PART-ONE');perform set_config('refund.first',r::text,true);
 if public.approve_order_refund(c,p,items,'QA-PART-ONE')<>r then raise exception 'FAIL: duplicate approved refund';end if;
 begin perform public.approve_order_refund(c,p,jsonb_build_array(jsonb_build_object('itemId',current_setting('refund.item'),'amountMinor',50)),'QA-PART-ONE');raise exception 'FAIL: changed financial retry';exception when invalid_parameter_value then null;end;
 begin perform public.approve_order_refund(c,p,jsonb_build_array(jsonb_build_object('itemId',current_setting('refund.item'),'amountMinor',80)),'QA-EXCESS');raise exception 'FAIL: pending refund over-allocation';exception when serialization_failure then null;end;
 r2:=public.approve_order_refund(c,p,jsonb_build_array(jsonb_build_object('itemId',current_setting('refund.item'),'amountMinor',60)),'QA-PART-TWO');perform set_config('refund.second',r2::text,true);
 begin perform public.resolve_return_case(c,2,'closed','Synthetic resolved note');raise exception 'FAIL: close while refunds pending';exception when serialization_failure then null;end;
 if has_function_privilege('authenticated','public.apply_order_refund(uuid,text,text,bigint,text,text)','execute')or has_function_privilege('authenticated','public.claim_order_refunds(text,boolean,integer)','execute')then raise exception 'FAIL: browser refund settlement grant';end if;
 if has_table_privilege('authenticated','private.order_refunds','select,insert,update,delete')then raise exception 'FAIL: direct financial ledger access';end if;
end $$;
reset role;
do $$declare jobs jsonb;report jsonb;r uuid:=current_setting('refund.first')::uuid;r2 uuid:=current_setting('refund.second')::uuid;begin
 perform set_config('request.jwt.claims','{}',true);
 jobs:=public.claim_order_refunds('stripe',false,10);
 if jsonb_array_length(jobs)<>2 or exists(select 1 from jsonb_array_elements(jobs)j where j->>'firstSubmission'<>'true')then raise exception 'FAIL: first dispatch claims';end if;
 perform set_config('refund.lease',(select j->>'lease'from jsonb_array_elements(jobs)j where j->>'id'=r::text),true);
 if public.claim_order_refunds('stripe',false,10)<>'[]'::jsonb then raise exception 'FAIL: duplicate live refund lease';end if;
 update private.order_refunds set lease_until=now()-interval '1 minute'where id=r;
 jobs:=public.claim_order_refunds('stripe',false,10);
 if jsonb_array_length(jobs)<>1 or jobs->0->>'firstSubmission'<>'false'then raise exception 'FAIL: uncertain request permits duplicate first submission';end if;
 perform public.flag_order_refund(r,current_setting('refund.lease')::uuid);
 if(select phase from private.order_refunds where id=r)<>'processing'then raise exception 'FAIL: old lease changed financial state';end if;
 begin perform public.apply_order_refund(r,'re_qa_first',current_setting('refund.payment'),41,'PHP','succeeded');raise exception 'FAIL: mismatched provider amount';exception when invalid_parameter_value then null;end;
 begin perform public.apply_order_refund(r,'re_qa_first','pi_wrong',40,'PHP','succeeded');raise exception 'FAIL: mismatched original payment';exception when invalid_parameter_value then null;end;
 perform public.apply_order_refund(r,'re_qa_first',current_setting('refund.payment'),40,'PHP','pending');
 if(select refunded_minor from public.orders where id=current_setting('refund.order')::uuid)<>0 then raise exception 'FAIL: pending refund marked received';end if;
 perform public.apply_order_refund(r,'re_qa_first',current_setting('refund.payment'),40,'PHP','succeeded');
 if(select refunded_minor from public.orders where id=current_setting('refund.order')::uuid)<>40 or(select payment_status from public.orders where id=current_setting('refund.order')::uuid)<>'paid'then raise exception 'FAIL: partial refund totals';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.admin'),'role','authenticated','aal','aal2')::text,true);
 report:=public.staff_sales_report((now()at time zone 'UTC')::date,(now()at time zone 'UTC')::date);
 if(report->>'refundsIncluded')is distinct from 'true'or(select x->>'netMinor'from jsonb_array_elements(report->'byProduct')x where x->>'productId'=current_setting('refund.product'))is distinct from '60'then raise exception 'FAIL: partial refund sales reporting';end if;
 perform set_config('request.jwt.claims','{}',true);
 perform public.apply_order_refund(r,'re_qa_first',current_setting('refund.payment'),40,'PHP','pending');
 if(select phase from private.order_refunds where id=r)<>'succeeded'then raise exception 'FAIL: late pending downgraded refund';end if;
 perform public.apply_order_refund(r2,'re_qa_second',current_setting('refund.payment'),60,'PHP','succeeded');
 if(select refunded_minor from public.orders where id=current_setting('refund.order')::uuid)<>100 or(select status from public.orders where id=current_setting('refund.order')::uuid)<>'refunded'then raise exception 'FAIL: full refund state';end if;
 if(select on_hand from public.inventory where product_id=current_setting('refund.product')::uuid and market='PH')<>9 then raise exception 'FAIL: money refund restocked unreceived goods';end if;
 if(select state from private.bonus_redemptions where order_id=current_setting('refund.order')::uuid)<>'consumed'then raise exception 'FAIL: paid gift capacity reused after refund';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.admin'),'role','authenticated','aal','aal2')::text,true);
 report:=public.staff_sales_report((now()at time zone 'UTC')::date,(now()at time zone 'UTC')::date);
 if(select x->>'netMinor'from jsonb_array_elements(report->'byProduct')x where x->>'productId'=current_setting('refund.product'))is distinct from '0'then raise exception 'FAIL: fully refunded order report';end if;
 if coalesce((select (x->>'refundedMinor')::bigint from jsonb_array_elements(report->'byMarket')x where x->>'market'='PH'),0)<100 then raise exception 'FAIL: verified refunds omitted';end if;
end $$;
set local role authenticated;
do $$declare receipt uuid;begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.user'),'role','authenticated','aal','aal1')::text,true);
 begin perform public.record_return_stock(current_setting('refund.case')::uuid,current_setting('refund.product')::uuid,1,'restock','QA-RECEIPT');raise exception 'FAIL: customer restock';exception when insufficient_privilege then null;end;
 if(public.return_context(current_setting('refund.order')::uuid)->>'refundedMinor')<>'100'then raise exception 'FAIL: customer financial status';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.admin'),'role','authenticated','aal','aal2')::text,true);
 receipt:=public.record_return_stock(current_setting('refund.case')::uuid,current_setting('refund.product')::uuid,1,'restock','QA-RECEIPT');
 if public.record_return_stock(current_setting('refund.case')::uuid,current_setting('refund.product')::uuid,1,'restock','QA-RECEIPT')<>receipt then raise exception 'FAIL: duplicate goods receipt';end if;
 perform public.record_return_stock(current_setting('refund.case')::uuid,current_setting('refund.gift')::uuid,1,'quarantine','QA-GIFT-RECEIPT');
 begin perform public.record_return_stock(current_setting('refund.case')::uuid,current_setting('refund.gift')::uuid,1,'restock','QA-GIFT-AGAIN');raise exception 'FAIL: returned bonus counted twice';exception when invalid_parameter_value then null;end;
 perform public.resolve_return_case(current_setting('refund.case')::uuid,2,'closed','Synthetic return and refund completed.');
end $$;
reset role;
do $$declare j jsonb;exported jsonb;begin
 if(select on_hand from public.inventory where product_id=current_setting('refund.product')::uuid and market='PH')<>10 then raise exception 'FAIL: returned goods not restocked once';end if;
 if(select on_hand from public.inventory where product_id=current_setting('refund.gift')::uuid and market='PH')<>9 then raise exception 'FAIL: quarantined gift entered sellable stock';end if;
 if(select count(*)from private.notification_jobs where kind='return_update'and context->>'orderId'=current_setting('refund.order'))<>4 then raise exception 'FAIL: return/refund notices are missing or duplicated';end if;
 for j in select value from jsonb_array_elements(public.claim_notifications())where value->>'kind'='return_update'loop
  if not public.notification_authorized((j->>'id')::uuid,(j->>'lease')::uuid)then raise exception 'FAIL: own transactional return notice suppressed';end if;
  if public.notification_authorized((j->>'id')::uuid,gen_random_uuid())then raise exception 'FAIL: incorrect notice lease accepted';end if;
 end loop;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.user'),'role','authenticated','aal','aal1')::text,true);
 exported:=public.export_my_data();
 if jsonb_array_length(exported->'returnCases')<>1 or jsonb_array_length(exported->'refunds')<>2 or exported::text like '%provider_payment_id%'then raise exception 'FAIL: own return/refund data export';end if;
end $$;
-- A policy change invalidates a quote, but cannot rewrite an accepted order's
-- terms. Cancellation releases only an undispatched refund allocation.
do $$declare q jsonb;o uuid;attempt jsonb;c uuid;refund uuid;jobs jsonb;items jsonb:=jsonb_build_array(jsonb_build_object('productId',current_setting('refund.product'),'quantity',1));begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.user'),'role','authenticated','aal','aal1')::text,true);
 q:=public.quote_fulfilment_checkout('PH',items,null,'{"method":"delivery"}');
 if q->'refundPolicy'->>'policyId'<>current_setting('refund.policy')then raise exception 'FAIL: refund terms not quoted';end if;
 o:=public.create_fulfilment_order('PH',items,'{"full_name":"QA Customer","phone":"0000000000","line1":"QA fixture address","city":"Manila","postal_code":"1000","country":"PH"}',gen_random_uuid(),(select checkout_terms_version from public.markets where code='PH'),null,q->>'quoteHash',null,'{"method":"delivery"}');
 if(select refund_policy_snapshot->>'policyId'from public.orders where id=o)<>current_setting('refund.policy')then raise exception 'FAIL: refund policy not frozen';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.admin'),'role','authenticated','aal','aal1')::text,true);
 begin perform public.withdraw_refund_policy(current_setting('refund.policy')::uuid);raise exception 'FAIL: policy withdrawal without MFA';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.admin'),'role','authenticated','aal','aal2')::text,true);
 perform public.withdraw_refund_policy(current_setting('refund.policy')::uuid);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.user'),'role','authenticated','aal','aal1')::text,true);
 begin perform public.create_fulfilment_order('PH',items,'{"full_name":"QA Customer","phone":"0000000000","line1":"QA fixture address","city":"Manila","postal_code":"1000","country":"PH"}',gen_random_uuid(),(select checkout_terms_version from public.markets where code='PH'),null,q->>'quoteHash',null,'{"method":"delivery"}');raise exception 'FAIL: stale refund-policy quote accepted';exception when serialization_failure then null;end;
 perform set_config('request.jwt.claims','{}',true);
 attempt:=public.prepare_stripe_checkout(o,current_setting('refund.user')::uuid,false,'https://example.invalid');
 perform public.apply_stripe_checkout_event('evt_frozen_'||o,(attempt->>'id')::uuid,o,'cs_test_frozen',false,100,'php','complete','paid','pi_frozen');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.user'),'role','authenticated','aal','aal1')::text,true);
 c:=public.request_order_return(o,'paid_cancellation','Synthetic paid cancellation under original terms');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.admin'),'role','authenticated','aal','aal2')::text,true);
 begin perform public.approve_order_refund(c,current_setting('refund.policy')::uuid,(select jsonb_build_array(jsonb_build_object('itemId',id,'amountMinor',40))from public.order_items where order_id=o),'QA-FROZEN-PARTIAL');raise exception 'FAIL: partial paid cancellation';exception when serialization_failure then null;end;
 refund:=public.approve_order_refund(c,current_setting('refund.policy')::uuid,(select jsonb_build_array(jsonb_build_object('itemId',id,'amountMinor',100))from public.order_items where order_id=o),'QA-FROZEN-FULL');
 perform public.manage_order_refund(refund,'cancel',null);
 if(public.return_context(o)->>'remainingMinor')<>'100'then raise exception 'FAIL: undispatched cancellation did not release funds';end if;
 refund:=public.approve_order_refund(c,current_setting('refund.policy')::uuid,(select jsonb_build_array(jsonb_build_object('itemId',id,'amountMinor',100))from public.order_items where order_id=o),'QA-FROZEN-RETRY');
 perform set_config('request.jwt.claims','{}',true);
 jobs:=public.claim_order_refunds('stripe',false,10);
 if jsonb_array_length(jobs)<>1 then raise exception 'FAIL: withdrawn policy dropped an accepted approval';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('refund.admin'),'role','authenticated','aal','aal2')::text,true);
 begin perform public.manage_order_refund(refund,'cancel',null);raise exception 'FAIL: cancellation after dispatch permitted';exception when serialization_failure then null;end;
 perform public.manage_order_refund(refund,'reconcile','re_canonical_candidate');
 if(select first_dispatched_at from private.order_refunds where id=refund)is null then raise exception 'FAIL: manual candidate erased dispatch intent';end if;
 update private.order_refunds set lease_until=now()-interval '1 minute'where id=refund;
 jobs:=public.claim_order_refunds('stripe',false,10);
 if jsonb_array_length(jobs)<>1 or jobs->0->>'firstSubmission'is distinct from 'false'or jobs->0->>'providerRefundId'is distinct from 're_canonical_candidate'then raise exception 'FAIL: manual candidate caused resubmission';end if;
 update private.order_refunds set attempts=12,lease_until=now()-interval '1 minute'where id=refund;
 jobs:=public.claim_order_refunds('stripe',false,10);
 if jobs<>'[]'::jsonb or(select phase from private.order_refunds where id=refund)is distinct from 'review'then raise exception 'FAIL: exhausted refund not held for review';end if;
end $$;
rollback;
